inline void preprocess(const uint16_t* raw,float* input) {
    uint32_t sum=0; for(int i=0;i<2400;++i) sum+=raw[i];
    float mean=float(sum)/2400.0f;
    const double pi=3.14159265358979323846;
    for(int k=0;k<1201;++k) {
        double re=0,im=0;
        for(int i=0;i<2400;++i) {
            float time=(float(raw[i])-mean)/2048.0f;
            double value=double(time)*hann[i];
            double angle=2.0*pi*k*i/2400.0;
            re+=value*std::cos(angle); im-=value*std::sin(angle);
        }
        input[k]=float(std::sqrt(re*re+im*im)/2400.0);
    }
}
// Ordered inputs P01, P02, P03. Preprocess each hit independently.
// input has 3603 floats; point_scratch has 1201 floats.
inline void preprocess_three(const uint16_t* p1,const uint16_t* p2,const uint16_t* p3,
                             float* input,float* point_scratch) {
    const uint16_t* points[3]={p1,p2,p3};
    for(int p=0;p<3;++p) {
        preprocess(points[p],point_scratch);
        for(int i=0;i<1201;++i) input[i*3+p]=point_scratch[i];
    }
}
// Use this entry point for direction-independent three-hit classification.
// reverse_input requires 3603 floats, separate from input and scratch.
inline void infer_either_direction(const float* input,float* scores,float* scratch,float* reverse_input) {
    for(int i=0;i<1201;++i) for(int p=0;p<3;++p) reverse_input[i*3+p]=input[i*3+2-p];
    float reversed_scores[2];
    infer(input,scores,scratch); infer(reverse_input,reversed_scores,scratch);
    for(int p=0;p<2;++p) scores[p]=(scores[p]+reversed_scores[p])*0.5f;
}
